import "server-only";

import { clienteTmdbPadrao, type ClienteTmdb, type Parametros } from "@/lib/tmdb/cliente";
import {
  anoDe,
  elencoDe,
  nuloSe404,
  ondeAssistirDe,
  paraGeneros,
  paraPagina,
  parametrosDescoberta,
  trailerDe,
  validar,
} from "@/lib/tmdb/comum";
import {
  detalhesSerieTmdb,
  generosTmdb,
  serieTmdb,
  type DetalhesSerieTmdb,
  type SerieTmdb,
} from "@/lib/tmdb/esquemas";
import type {
  ClassificacaoBR,
  FiltrosDescobertaSerie,
  OrdemDescoberta,
  Pagina,
  SerieDetalhes,
  SerieResumo,
} from "@/lib/tmdb/tipos";

const HORA = 3600;
const CACHE_LISTAS = 6 * HORA;
const CACHE_SERIE = 24 * HORA;

const ORDENS: Record<OrdemDescoberta, string> = {
  popularidade: "popularity.desc",
  nota: "vote_average.desc",
  lancamento: "first_air_date.desc",
};

/** Classificações do Brasil, da mais leve à mais restrita. */
export const CLASSIFICACOES_BR: readonly ClassificacaoBR[] = ["L", "10", "12", "14", "16", "18"];

function paraResumo(serie: SerieTmdb): SerieResumo {
  return {
    id: serie.id,
    titulo: serie.name,
    tituloOriginal: serie.original_name,
    sinopse: serie.overview,
    posterPath: serie.poster_path,
    backdropPath: serie.backdrop_path,
    generos: serie.genre_ids,
    ano: anoDe(serie.first_air_date),
    nota: serie.vote_average,
    votos: serie.vote_count,
    popularidade: serie.popularity,
  };
}

/** Média de `episode_run_time`; sem ela, a duração do último episódio exibido. */
function duracaoEpisodio(serie: DetalhesSerieTmdb): number | null {
  const duracoes = serie.episode_run_time.filter((minutos) => minutos > 0);
  if (duracoes.length === 0) return serie.last_episode_to_air?.runtime || null;
  return Math.round(duracoes.reduce((soma, minutos) => soma + minutos, 0) / duracoes.length);
}

function classificacaoDe(serie: DetalhesSerieTmdb): ClassificacaoBR | null {
  const doBrasil = serie.content_ratings.results.find((r) => r.iso_3166_1 === "BR")?.rating;
  return CLASSIFICACOES_BR.find((classificacao) => classificacao === doBrasil) ?? null;
}

function paraDetalhes(serie: DetalhesSerieTmdb): SerieDetalhes {
  return {
    ...paraResumo({ ...serie, genre_ids: [] }),
    generos: paraGeneros(serie.genres),
    duracaoEpisodioMin: duracaoEpisodio(serie),
    temporadas: serie.seasons
      .filter((temporada) => temporada.season_number > 0)
      .sort((a, b) => a.season_number - b.season_number)
      .map((temporada) => ({
        numero: temporada.season_number,
        nome: temporada.name,
        episodios: temporada.episode_count,
        ano: anoDe(temporada.air_date),
        posterPath: temporada.poster_path,
      })),
    slogan: serie.tagline,
    trailerYoutube: trailerDe(serie.videos.results),
    elenco: elencoDe(serie.credits),
    criacao: serie.created_by.map((pessoa) => pessoa.name),
    classificacao: classificacaoDe(serie),
    ondeAssistir: ondeAssistirDe(serie["watch/providers"]),
  };
}

/** Funções de séries sobre um cliente qualquer; os testes passam um cliente com `fetch` falso. */
export function criarApiSeries(cliente: ClienteTmdb) {
  return {
    async descobrirSeries(filtros: FiltrosDescobertaSerie = {}): Promise<Pagina<SerieResumo>> {
      const parametros: Parametros = {
        ...parametrosDescoberta(filtros, ORDENS),
        first_air_date_year: filtros.ano,
        "first_air_date.lte": filtros.lancadoAte,
      };
      const dados = await cliente.requisitar("/discover/tv", parametros, CACHE_LISTAS);
      return paraPagina(serieTmdb, dados, paraResumo);
    },

    obterSerie(id: number): Promise<SerieDetalhes | null> {
      return nuloSe404(async () => {
        const dados = await cliente.requisitar(
          `/tv/${id}`,
          { append_to_response: "videos,credits,watch/providers,content_ratings" },
          CACHE_SERIE,
        );
        return paraDetalhes(validar(detalhesSerieTmdb, dados));
      });
    },

    /** Gêneros de TV: outra lista que a dos filmes, com IDs próprios. */
    async generosSeries(): Promise<{ id: number; nome: string }[]> {
      const dados = await cliente.requisitar("/genre/tv/list", {}, CACHE_SERIE);
      return paraGeneros(validar(generosTmdb, dados).genres);
    },
  };
}

export type ApiSeries = ReturnType<typeof criarApiSeries>;

let padrao: ApiSeries | undefined;
const api = () => (padrao ??= criarApiSeries(clienteTmdbPadrao()));

export const descobrirSeries: ApiSeries["descobrirSeries"] = (...args) =>
  api().descobrirSeries(...args);
export const obterSerie: ApiSeries["obterSerie"] = (...args) => api().obterSerie(...args);
export const generosSeries: ApiSeries["generosSeries"] = () => api().generosSeries();

import { cn } from "cn";
import Link from "next/link";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { ORDENS, type FiltrosBusca, type Modo } from "@/features/busca/parametros";
import { GENEROS } from "@/features/preferencias/generos";
import { ROTULOS_DURACAO, type Duracao } from "@/features/preferencias/opcoes";
import type { OrdemDescoberta } from "@/lib/tmdb/tipos";

const ROTULOS_ORDEM: Record<OrdemDescoberta, string> = {
  popularidade: "Mais populares",
  nota: "Mais bem avaliados",
  lancamento: "Lançamentos",
};

const DURACOES_FILTRO: Duracao[] = ["indiferente", "curta", "media", "longa"];

const estiloSelect =
  "border-input bg-background dark:bg-input/30 focus-visible:border-ring focus-visible:ring-ring/50 h-10 w-full rounded-lg border px-2.5 text-sm outline-none focus-visible:ring-3";

export function AbasBusca({ ativa }: { ativa: Modo }) {
  const abas: { modo: Modo; rotulo: string; href: string }[] = [
    { modo: "nome", rotulo: "Por nome", href: "/busca" },
    { modo: "filtros", rotulo: "Por filtros", href: "/busca?modo=filtros" },
  ];
  return (
    <nav aria-label="Modo de busca" className="border-border flex gap-1 border-b">
      {abas.map(({ modo, rotulo, href }) => (
        <Link
          key={modo}
          href={href}
          aria-current={modo === ativa ? "page" : undefined}
          className={cn(
            "-mb-px border-b-2 px-4 py-2 text-sm font-medium transition-colors",
            modo === ativa
              ? "border-primary text-foreground"
              : "text-muted-foreground hover:text-foreground border-transparent",
          )}
        >
          {rotulo}
        </Link>
      ))}
    </nav>
  );
}

export function FormularioNome({ texto }: { texto: string }) {
  return (
    <form action="/busca" method="get" role="search" className="flex flex-wrap items-end gap-3">
      <div className="flex min-w-48 flex-1 flex-col gap-2">
        <Label htmlFor="busca-q">Nome do filme</Label>
        <Input id="busca-q" name="q" type="search" defaultValue={texto} className="h-10" />
      </div>
      <Button type="submit" size="lg" className="h-10 px-5">
        Buscar
      </Button>
    </form>
  );
}

export function FormularioFiltros({ filtros }: { filtros: FiltrosBusca }) {
  return (
    <form
      action="/busca"
      method="get"
      className="grid grid-cols-1 items-end gap-4 sm:grid-cols-2 lg:grid-cols-1"
    >
      <input type="hidden" name="modo" value="filtros" />
      <div className="flex flex-col gap-2">
        <Label htmlFor="filtro-genero">Gênero</Label>
        <select
          id="filtro-genero"
          name="genero"
          defaultValue={filtros.genero ?? ""}
          className={estiloSelect}
        >
          <option value="">Todos</option>
          {GENEROS.map(({ id, nome }) => (
            <option key={id} value={id}>
              {nome}
            </option>
          ))}
        </select>
      </div>
      <div className="flex flex-col gap-2">
        <Label htmlFor="filtro-ano">Ano de lançamento</Label>
        <Input
          id="filtro-ano"
          name="ano"
          type="number"
          inputMode="numeric"
          min={1888}
          placeholder="Qualquer"
          defaultValue={filtros.ano ?? ""}
          className="h-10"
        />
      </div>
      <div className="flex flex-col gap-2">
        <Label htmlFor="filtro-duracao">Duração</Label>
        <select
          id="filtro-duracao"
          name="duracao"
          defaultValue={filtros.duracao}
          className={estiloSelect}
        >
          {DURACOES_FILTRO.map((duracao) => (
            <option key={duracao} value={duracao}>
              {ROTULOS_DURACAO[duracao]}
            </option>
          ))}
        </select>
      </div>
      <div className="flex flex-col gap-2">
        <Label htmlFor="filtro-ordem">Ordenar por</Label>
        <select
          id="filtro-ordem"
          name="ordem"
          defaultValue={filtros.ordem}
          className={estiloSelect}
        >
          {ORDENS.map((ordem) => (
            <option key={ordem} value={ordem}>
              {ROTULOS_ORDEM[ordem]}
            </option>
          ))}
        </select>
      </div>
      <Button type="submit" size="lg" className="h-10 px-5">
        Aplicar filtros
      </Button>
    </form>
  );
}
import Link from "next/link";

import { buttonVariants } from "@/components/ui/button";

const MAX_PAGINAS_TMDB = 500;

type Props = {
  /** Parâmetros da busca que cada link de página mantém. */
  parametros: Record<string, string>;
  pagina: number;
  totalPaginas: number;
};

export function Paginacao({ parametros, pagina, totalPaginas }: Props) {
  const total = Math.min(totalPaginas, MAX_PAGINAS_TMDB);
  if (total <= 1) return null;

  const href = (numero: number) =>
    `/busca?${new URLSearchParams({ ...parametros, pagina: String(numero) })}`;

  return (
    <nav aria-label="Paginação" className="flex items-center justify-center gap-4 py-4">
      {pagina > 1 && (
        <Link href={href(pagina - 1)} className={buttonVariants({ variant: "outline" })}>
          Anterior
        </Link>
      )}
      <span className="text-muted-foreground text-sm">
        Página {pagina} de {total}
      </span>
      {pagina < total && (
        <Link href={href(pagina + 1)} className={buttonVariants({ variant: "outline" })}>
          Próxima
        </Link>
      )}
    </nav>
  );
}
import { Paginacao } from "@/features/busca/components/paginacao";
import { MIN_TEXTO, type Modo } from "@/features/busca/parametros";
import { CartaoFilme } from "@/features/dashboard/components/cartao-filme";
import type { FilmeResumo, Pagina } from "@/lib/tmdb/tipos";

const numeroPtBr = new Intl.NumberFormat("pt-BR");

type Props = {
  modo: Modo;
  texto: string;
  /** `null` quando não houve consulta (texto curto demais no modo nome). */
  resultado: Pagina<FilmeResumo> | null;
  parametros: Record<string, string>;
};

function cabecalho(modo: Modo, total: number, texto: string) {
  const quantidade = numeroPtBr.format(total);
  if (modo === "nome") {
    return `${quantidade} ${total === 1 ? "resultado" : "resultados"} para “${texto}”`;
  }
  return `${quantidade} ${total === 1 ? "filme encontrado" : "filmes encontrados"}`;
}

export function ResultadosBusca({ modo, texto, resultado, parametros }: Props) {
  if (!resultado || (modo === "nome" && texto.length < MIN_TEXTO)) {
    return <p className="text-muted-foreground">Digite o nome de um filme para começar.</p>;
  }

  if (resultado.itens.length === 0) {
    return (
      <p className="text-muted-foreground">
        {modo === "nome"
          ? `Nenhum filme encontrado para “${texto}”.`
          : "Nenhum filme encontrado com esses filtros."}
      </p>
    );
  }

  return (
    <div className="flex flex-col gap-6">
      <p className="text-muted-foreground">{cabecalho(modo, resultado.totalResultados, texto)}</p>
      <ul className="grid grid-cols-[repeat(auto-fill,minmax(10rem,1fr))] gap-6">
        {resultado.itens.map((filme) => (
          <li key={filme.id}>
            <CartaoFilme filme={filme} />
          </li>
        ))}
      </ul>
      <Paginacao
        parametros={parametros}
        pagina={resultado.pagina}
        totalPaginas={resultado.totalPaginas}
      />
    </div>
  );
}
