      rotulo="Tipo de título"
      ativa={ativa}
      abas={[
        { valor: "filme", rotulo: "Filmes", href: href("filme") },
        { valor: "serie", rotulo: "Séries", href: href("serie") },
      ]}
    />
  );
}

